maxsize=1048576; find . -type f \( -iname "*.jpg" -o -iname "*.png" \) -exec sh -c 'maxsize='"$maxsize"'; filesize=$(stat -f%z "$1"); if [ $filesize -gt $maxsize ]; then magick "$1" -resize 1400x1400\> -quality 90 -strip "$1"; filesize=$(stat -f%z "$1"); maxdim=1400; while [ $filesize -gt $maxsize ] && [ $maxdim -gt 600 ]; do magick "$1" -resize ${maxdim}x${maxdim}\> -quality 90 -strip "$1"; filesize=$(stat -f%z "$1"); maxdim=$((maxdim - 100)); done; echo "Processed: $1 (final size: $filesize bytes)"; fi' sh {} \;